// Compares usage/help rendering across terminal widths.
import { runPy, runJs, normalizeStderr, report } from './lib.mjs';
const K = '0123456789012345';
const widths = [null, 10, 15, 20, 24, 25, 28, 30, 35, 40, 45, 50, 55, 60, 70, 78, 80, 100, 200];
const argvs = [['-h'], ['--help'], [], ['--key1', K], ['--key', K, '--key2', K, '--data', K],
  ['--key1', K, '--key2', K, '--data', K, '--extra', 'x'], ['--key1']];
const failures = [];
let total = 0;
for (const w of widths) for (const argv of argvs) {
  total++;
  const env = w === null ? {} : { COLUMNS: String(w) };
  const a = runPy(argv, env), b = runJs(argv, env);
  const label = [...argv, `COLUMNS=${w}`];
  if (a.code !== b.code) failures.push({ argv: label, field: 'exit code', expected: a.code, actual: b.code });
  else if (normalizeStderr(a.stdout) !== normalizeStderr(b.stdout)) failures.push({ argv: label, field: 'stdout', expected: normalizeStderr(a.stdout), actual: normalizeStderr(b.stdout) });
  else if (normalizeStderr(a.stderr) !== normalizeStderr(b.stderr)) failures.push({ argv: label, field: 'stderr', expected: normalizeStderr(a.stderr), actual: normalizeStderr(b.stderr) });
}
process.exit(report('width', failures, total) ? 0 : 1);
