import { readFileSync } from 'node:fs';
import { runJs, normalizeStderr, report } from './lib.mjs';

const cases = JSON.parse(readFileSync('/workspace/harness/cli_cases.json', 'utf8'));
const failures = [];
for (const c of cases) {
  const got = runJs(c.argv);
  if (got.code !== c.code) failures.push({ argv: c.argv, field: 'exit code', expected: c.code, actual: got.code });
  else if (got.stdout !== c.stdout) failures.push({ argv: c.argv, field: 'stdout', expected: c.stdout, actual: got.stdout });
  else {
    const exp = normalizeStderr(c.stderr), act = normalizeStderr(got.stderr);
    if (exp !== act) failures.push({ argv: c.argv, field: 'stderr (normalized)', expected: exp, actual: act });
  }
}
process.exit(report('cli', failures, cases.length) ? 0 : 1);
